static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* xShape = context->GetInputShape(0);
    const gert::Shape* wShape = context->GetInputShape(1);
    if (xShape->GetDimNum() != 5 || wShape->GetDimNum() != 5) {
        return GRAPH_FAILED;
    }
    uint64_t N  = xShape->GetDim(0);
    uint64_t Di = xShape->GetDim(2);
    uint64_t Hi = xShape->GetDim(3);
    uint64_t Wi = xShape->GetDim(4);
    uint64_t Kd = wShape->GetDim(2);
    uint64_t Kh = wShape->GetDim(3);
    uint64_t Kw = wShape->GetDim(4);
    uint64_t Cout = wShape->GetDim(1);

    // 仅支持 stride=1, padding=0, output_padding=0
    uint64_t Do = Di + Kd - 1;
    uint64_t Ho = Hi + Kh - 1;
    uint64_t Wo = Wi + Kw - 1;

    gert::Shape* yShape = context->GetOutputShape(0);
    yShape->SetDimNum(5);
