at::Tensor conv_transposed_3d_asymmetric_input_asymmetric_kernel_custom_impl_npu(const at::Tensor& x, const at::Tensor& w) {
    TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
    TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout, Kd, Kh, Kw]");
    TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat, "only float32 supported");

    auto N = x.size(0);
    auto Di = x.size(2);
    auto Hi = x.size(3);
    auto Wi = x.size(4);
    auto Cout = w.size(1);
    auto Kd = w.size(2);
    auto Kh = w.size(3);
    auto Kw = w.size(4);

    // 仅支持 stride=1, padding=0, output_padding=0
    auto Do = Di + Kd - 1;
    auto Ho = Hi + Kh - 1;
    auto Wo = Wi + Kw - 1;

    at::Tensor y = at::empty({N, Cout, Do, Ho, Wo}, x.options());
    EXEC_NPU_CMD(aclnnConvTransposed3dAsymmetricInputAsymmetricKernelCustom, x, w, y);
    return y;
}

